import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx, row

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("ZIP entries:", names)
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for s in wb.find('m:sheets', NS):
        sheets.append((s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("Sheets:", sheets)

    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels:
        rel_map[rel.get('Id')] = rel.get('Target')

    shared = []
    if 'xl/sharedStrings.xml' in names:
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for name, rid in sheets:
        target = rel_map[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target
        print(f"\n=== Sheet: {name} ===")
        ws = ET.fromstring(z.read(target))
        rows = {}
        for row in ws.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            rnum = int(row.get('r'))
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                raw = None
                if t == 's' and v is not None:
                    raw = shared[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    raw = ''.join(x.text or '' for x in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                elif t == 'str' and v is not None:
                    raw = v.text
                elif v is not None:
                    raw = v.text
                if raw is not None:
                    rows[ref] = raw
        max_col = 0
        for ref in rows:
            ci, _ = col_to_idx(ref)
            max_col = max(max_col, ci)
        grid = []
        for ref in sorted(rows, key=lambda r: (col_to_idx(r)[1], col_to_idx(r)[0])):
            ci, ri = col_to_idx(ref)
            while len(grid) < ri:
                grid.append([])
            while len(grid[ri - 1]) < ci:
                grid[ri - 1].append('')
            grid[ri - 1][ci - 1] = rows[ref]
        for i, g in enumerate(grid, 1):
            print(f"R{i}: {g}")

